// SEMANA 14 - SESIÓN 2 (Paso 7): pantalla «Tareas en la nube».
//
// TODO(Paso 7): crea TareasRemotasScreen (ConsumerWidget) que:
//   - observe tareasRemotasProvider con ref.watch;
//   - use .when(loading:, error:, data:) para que ninguna pantalla
//     quede en blanco;
//   - muestre una vista de error con texto y botón "Reintentar";
//   - permita recargar deslizando hacia abajo (RefreshIndicator);
//   - tenga un FloatingActionButton que abra NuevaTareaScreen
//     (Semana 13, sin modificarla) y envíe la tarea con crear().
//
// TODO(Paso 7): después de cada await, verifica context.mounted
//               antes de usar el context.
//
// TODO(Paso 9): realiza las cuatro pruebas de fallos y documenta
//               lo que ve el usuario en cada una.
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../datos/tareas_api.dart' show ApiException;
import '../estado/tareas_remotas_provider.dart';
import '../modelos/tarea.dart';
import 'nueva_tarea_screen.dart';

class TareasRemotasScreen extends ConsumerWidget {
  const TareasRemotasScreen({super.key});

    Future<void> _nueva(BuildContext context, WidgetRef ref) async {
        final nueva = await Navigator.push<Tarea>(
              context,
                    MaterialPageRoute(builder: (_) => const NuevaTareaScreen()),
                        );
                            if (nueva == null) return;
                                try {
                                      await ref.read(tareasRemotasProvider.notifier).crear(nueva);
                                            if (!context.mounted) return;
                                                  ScaffoldMessenger.of(context).showSnackBar(
                                                          SnackBar(content: Text('Tarea "${nueva.titulo}" enviada')),
                                                                );
                                                                    } on ApiException catch (e) {
                                                                          if (!context.mounted) return;
                                                                                ScaffoldMessenger.of(context).showSnackBar(
                                                                                        SnackBar(content: Text(e.mensaje)),
                                                                                              );
                                                                                                  }
                                                                                                    }

                                                                                                      @override
                                                                                                        Widget build(BuildContext context, WidgetRef ref) {
                                                                                                            final estado = ref.watch(tareasRemotasProvider);
                                                                                                                final notifier = ref.read(tareasRemotasProvider.notifier);

                                                                                                                    return Scaffold(
                                                                                                                          appBar: AppBar(title: const Text('Tareas en la nube')),
                                                                                                                                body: estado.when(
                                                                                                                                        loading: () => const Center(child: CircularProgressIndicator()),
                                                                                                                                                error: (error, _) => _VistaError(
                                                                                                                                                          mensaje: error is ApiException
                                                                                                                                                                        ? error.mensaje
                                                                                                                                                                                      : 'Ocurrió un error inesperado.',
                                                                                                                                                                                                onReintentar: notifier.recargar,
                                                                                                                                                                                                        ),
                                                                                                                                                                                                                data: (tareas) => RefreshIndicator(
                                                                                                                                                                                                                          onRefresh: notifier.recargar,
                                                                                                                                                                                                                                    child: tareas.isEmpty
                                                                                                                                                                                                                                                  ? ListView(
                                                                                                                                                                                                                                                                    physics: const AlwaysScrollableScrollPhysics(),
                                                                                                                                                                                                                                                                                      children: const [
                                                                                                                                                                                                                                                                                                          SizedBox(height: 200),
                                                                                                                                                                                                                                                                                                                              Center(child: Text('No hay tareas en la nube.')),
                                                                                                                                                                                                                                                                                                                                                ],
                                                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                                                              : ListView.separated(
                                                                                                                                                                                                                                                                                                                                                                                                physics: const AlwaysScrollableScrollPhysics(),
                                                                                                                                                                                                                                                                                                                                                                                                                  padding: const EdgeInsets.only(bottom: 88),
                                                                                                                                                                                                                                                                                                                                                                                                                                    itemCount: tareas.length,
                                                                                                                                                                                                                                                                                                                                                                                                                                                      separatorBuilder: (_, _) => const Divider(height: 1),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        itemBuilder: (context, i) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            final t = tareas[i];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return ListTile(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      leading: Icon(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              t.completada
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ? Icons.check_circle
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      : Icons.radio_button_unchecked,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  title: Text(t.titulo),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        subtitle: Text('ID ${t.id ?? '-'}'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  floatingActionButton: FloatingActionButton.extended(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          icon: const Icon(Icons.add),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  label: const Text('Nueva tarea'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onPressed: () => _nueva(context, ref),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      class _VistaError extends StatelessWidget {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const _VistaError({required this.mensaje, required this.onReintentar});

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          final String mensaje;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            final VoidCallback onReintentar;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              @override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Widget build(BuildContext context) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return Center(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          child: Padding(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  padding: const EdgeInsets.all(24),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          child: Column(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mainAxisSize: MainAxisSize.min,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const Icon(Icons.cloud_off, size: 48),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const SizedBox(height: 12),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Text(mensaje, textAlign: TextAlign.center),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const SizedBox(height: 16),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          FilledButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onPressed: onReintentar,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      child: const Text('Reintentar'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }